const [region, setRegion] = useState('eu')

<Grid gap={3}>
  {regions.map((r) => (
    <SelectableTile
      key={r.id}
      name="region"
      title={r.title}
      icon={r.icon}
      description={r.description}
      meta={r.meta}
      selected={region === r.id}
      onChange={() => setRegion(r.id)}
    />
  ))}
</Grid>
